import React, { useState } from "react";
import { AnimatePresence, motion } from "framer-motion";
import WorkerSplash from "./components/WorkerSplash";
import SignIn from "./components/SignIn";
import Dashboard from "./pages/Dashboard"; // Double-check the path is correct

function App() {
  const [view, setView] = useState("splash");

  return (
    // We use the hex directly to avoid unused-var warnings
    <motion.div 
      animate={{ backgroundColor: view === "splash" ? "#A1AED1" : "#FFF24D" }}
      transition={{ duration: 1, ease: [0.16, 1, 0.3, 1] }}
      className="h-screen w-full relative overflow-hidden"
    >
      <AnimatePresence mode="wait">
        {view === "splash" && (
          <motion.div
            key="splash"
            exit={{ y: "-100%", opacity: 0 }}
            transition={{ duration: 0.8, ease: [0.76, 0, 0.24, 1] }}
            className="absolute inset-0 z-50"
          >
            <WorkerSplash onComplete={() => setView("signin")} />
          </motion.div>
        )}

        {view === "signin" && (
          <motion.div
            key="signin"
            initial={{ y: "100%", opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
            className="absolute inset-0 z-40 flex items-center justify-center"
          >
            <SignIn onLogin={() => setView("dashboard")} />
          </motion.div>
        )}

        {view === "dashboard" && (
          <motion.div 
            key="dashboard"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="absolute inset-0 z-[60] bg-[#FDFAD8]"
          >
            {/* Dashboard Component will go here */}
                  {view === "dashboard" && (
        <motion.div 
          key="dashboard"
          initial={{ opacity: 0, scale: 1.05 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ duration: 0.8, ease: [0.16, 1, 0.3, 1] }}
          className="absolute inset-0 z-[60]"
        >
          <Dashboard />
        </motion.div>
      )}
          </motion.div>
        )}
      </AnimatePresence>
    </motion.div>
  );
}

export default App;
